      "source": "<template>\n  <div class=\"slds-grid slds-wrap slds-gutters_small\">\n    <div class=\"slds-col slds-size_1-of-1 slds-medium-size_1-of-2 slds-var-m-bottom_medium\">\n      <h3 class=\"slds-text-heading_small slds-var-m-bottom_x-small\">From configuration</h3>\n      <p class=\"slds-var-m-bottom_small slds-text-body_small\">\n        The Example_Account_Overview export: accounts, contacts and open opportunities, read as you.\n      </p>\n      <c-data-export\n        export-name=\"Example_Account_Overview\"\n        onexported={handleExported}\n        onexporterror={handleError}\n      ></c-data-export>\n    </div>\n\n    <div class=\"slds-col slds-size_1-of-1 slds-medium-size_1-of-2 slds-var-m-bottom_medium\">\n      <h3 class=\"slds-text-heading_small slds-var-m-bottom_x-small\">From the page's own data</h3>\n      <p class=\"slds-var-m-bottom_small slds-text-body_small\">\n        No configuration and no Apex: three invoices defined in the example, as a styled workbook.\n      </p>\n      <c-data-export\n        workbooks={workbooks}\n        label=\"Export invoices\"\n        formats=\"excel\"\n        variant=\"brand\"\n        onexported={handleExported}\n        onexporterror={handleError}\n      ></c-data-export>\n    </div>\n  </div>\n\n  <template lwc:if={summary}>\n    <p class=\"slds-text-body_small\">{summary}</p>\n  </template>\n</template>"
